package com.example.progfront.ui.home

import android.app.DatePickerDialog
import android.os.Bundle
import android.util.Log
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Button
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.Toast
import androidx.fragment.app.Fragment
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.example.progfront.databinding.FragmentHomeBinding
import com.example.progfront.network.RetrofitClient
import com.example.progfront.network.ScheduleResponse
import com.example.progfront.utils.TokenManager
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response
import java.text.SimpleDateFormat
import java.util.*

class HomeFragment : Fragment() {

    private var _binding: FragmentHomeBinding? = null
    private val binding get() = _binding!!

    private lateinit var tokenManager: TokenManager
    private lateinit var scheduleAdapter: ScheduleAdapter
    private lateinit var buttonSelectDate: Button
    private lateinit var recyclerViewSchedules: RecyclerView
    private lateinit var progressBar: ProgressBar
    private lateinit var layoutEmptyState: LinearLayout

    private var selectedDate: Calendar = Calendar.getInstance()

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentHomeBinding.inflate(inflater, container, false)
        val root: View = binding.root

        tokenManager = TokenManager(requireContext())

        initializeViews(root)
        setupRecyclerView()
        setupDatePicker()
        updateDateDisplay()

        // Load schedules for today initially
        loadSchedulesForDate()

        return root
    }

    private fun initializeViews(root: View) {
        buttonSelectDate = binding.buttonSelectDate
        recyclerViewSchedules = binding.recyclerViewSchedules
        progressBar = binding.progressBar
        layoutEmptyState = binding.layoutEmptyState
    }

    private fun setupRecyclerView() {
        scheduleAdapter = ScheduleAdapter(emptyList())
        recyclerViewSchedules.apply {
            layoutManager = LinearLayoutManager(requireContext())
            adapter = scheduleAdapter
        }
    }

    private fun setupDatePicker() {
        buttonSelectDate.setOnClickListener {
            showDatePickerDialog()
        }
    }

    private fun showDatePickerDialog() {
        val datePickerDialog = DatePickerDialog(
            requireContext(),
            { _, year, month, dayOfMonth ->
                selectedDate.set(year, month, dayOfMonth)
                updateDateDisplay()
                loadSchedulesForDate()
            },
            selectedDate.get(Calendar.YEAR),
            selectedDate.get(Calendar.MONTH),
            selectedDate.get(Calendar.DAY_OF_MONTH)
        )
        datePickerDialog.show()
    }

    private fun updateDateDisplay() {
        val today = Calendar.getInstance()
        val dateFormat = if (isSameDay(selectedDate, today)) {
            "Today"
        } else {
            SimpleDateFormat("MMM dd, yyyy", Locale.getDefault()).format(selectedDate.time)
        }
        buttonSelectDate.text = dateFormat
    }

    private fun isSameDay(cal1: Calendar, cal2: Calendar): Boolean {
        return cal1.get(Calendar.YEAR) == cal2.get(Calendar.YEAR) &&
                cal1.get(Calendar.DAY_OF_YEAR) == cal2.get(Calendar.DAY_OF_YEAR)
    }

    private fun loadSchedulesForDate() {
        val token = tokenManager.getBearerToken()

        Log.d("HomeFragment", "=== Starting loadSchedulesForDate ===")
        Log.d("HomeFragment", "Token exists: ${token != null}")
        Log.d("HomeFragment", "Selected date: ${selectedDate.time}")

        if (token == null) {
            Log.e("HomeFragment", "No valid token found - user needs to log in again")
            Toast.makeText(requireContext(), "Please log in again", Toast.LENGTH_SHORT).show()
            return
        }

        // Show loading indicator
        progressBar.visibility = View.VISIBLE
        recyclerViewSchedules.visibility = View.GONE
        layoutEmptyState.visibility = View.GONE

        // Format date for API call (YYYY-MM-DD)
        val dateFormat = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault())
        val dateString = dateFormat.format(selectedDate.time)

        Log.d("HomeFragment", "Formatted date string for API: '$dateString'")
        Log.d("HomeFragment", "Making API call to /schedule/day with date parameter: $dateString")

        RetrofitClient.instance.getSchedulesByDay(token, dateString)
            .enqueue(object : Callback<List<ScheduleResponse>> {
                override fun onResponse(call: Call<List<ScheduleResponse>>, response: Response<List<ScheduleResponse>>) {
                    progressBar.visibility = View.GONE

                    Log.d("HomeFragment", "=== API Response Received ===")
                    Log.d("HomeFragment", "Response code: ${response.code()}")
                    Log.d("HomeFragment", "Response successful: ${response.isSuccessful}")
                    Log.d("HomeFragment", "Response body: ${response.body()}")
                    Log.d("HomeFragment", "Response headers: ${response.headers()}")

                    if (!response.isSuccessful) {
                        val errorBody = response.errorBody()?.string()
                        Log.e("HomeFragment", "Error response: $errorBody")
                    }

                    if (response.isSuccessful) {
                        response.body()?.let { schedules ->
                            Log.d("HomeFragment", "Received ${schedules.size} schedules")
                            schedules.forEachIndexed { index, schedule ->
                                Log.d("HomeFragment", "Schedule $index: ID=${schedule.id}, Habit=${schedule.habit?.name}, Date=${schedule.date}, StartTime=${schedule.start_time}, Status=${schedule.status}")
                            }

                            if (schedules.isEmpty()) {
                                Log.d("HomeFragment", "No schedules found - showing empty state")
                                showEmptyState()
                            } else {
                                Log.d("HomeFragment", "Showing ${schedules.size} schedules")
                                showSchedules(schedules)
                            }
                        } ?: run {
                            Log.w("HomeFragment", "Response body is null - showing empty state")
                            showEmptyState()
                        }
                    } else {
                        val errorBody = response.errorBody()?.string()
                        Log.e("HomeFragment", "Failed to load schedules: Response code ${response.code()}, Error: $errorBody")
                        Toast.makeText(requireContext(), "Failed to load schedules", Toast.LENGTH_SHORT).show()
                        showEmptyState()
                    }
                }

                override fun onFailure(call: Call<List<ScheduleResponse>>, t: Throwable) {
                    progressBar.visibility = View.GONE
                    Log.e("HomeFragment", "=== API Call Failed ===")
                    Log.e("HomeFragment", "Network error loading schedules: ${t.message}", t)
                    Log.e("HomeFragment", "Exception type: ${t.javaClass.simpleName}")
                    Toast.makeText(requireContext(), "Network error: ${t.message}", Toast.LENGTH_SHORT).show()
                    showEmptyState()
                }
            })
    }

    private fun showSchedules(schedules: List<ScheduleResponse>) {
        scheduleAdapter.updateSchedules(schedules)
        recyclerViewSchedules.visibility = View.VISIBLE
        layoutEmptyState.visibility = View.GONE
    }

    private fun showEmptyState() {
        recyclerViewSchedules.visibility = View.GONE
        layoutEmptyState.visibility = View.VISIBLE
    }

    override fun onResume() {
        super.onResume()
        // Refresh schedules when returning to the fragment
        loadSchedulesForDate()
    }

    /**
     * Public method to refresh schedules - can be called from MainActivity
     * when returning from CreateScheduleActivity
     */
    fun refreshSchedules() {
        Log.d("HomeFragment", "refreshSchedules() called - reloading schedules for current date")
        loadSchedulesForDate()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.example.progfront.ui.home

import android.util.Log
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.TextView
import androidx.recyclerview.widget.RecyclerView
import com.example.progfront.R
import com.example.progfront.network.ScheduleResponse
import java.text.SimpleDateFormat
import java.util.*

class ScheduleAdapter(private var schedules: List<ScheduleResponse>) : RecyclerView.Adapter<ScheduleAdapter.ScheduleViewHolder>() {

    class ScheduleViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val statusIndicator: View = itemView.findViewById(R.id.statusIndicator)
        val textStartTime: TextView = itemView.findViewById(R.id.textStartTime)
        val textEndTime: TextView = itemView.findViewById(R.id.textEndTime)
        val textHabitName: TextView = itemView.findViewById(R.id.textHabitName)
        val textDuration: TextView = itemView.findViewById(R.id.textDuration)
        val textNotes: TextView = itemView.findViewById(R.id.textNotes)
        val textStatus: TextView = itemView.findViewById(R.id.textStatus)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ScheduleViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_schedule, parent, false)
        return ScheduleViewHolder(view)
    }

    override fun onBindViewHolder(holder: ScheduleViewHolder, position: Int) {
        val schedule = schedules[position]

        // Format and display start time
        try {
            val isoFormat = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", Locale.getDefault())
            val timeFormat = SimpleDateFormat("HH:mm", Locale.getDefault())
            val startTime = isoFormat.parse(schedule.start_time)
            holder.textStartTime.text = startTime?.let { timeFormat.format(it) } ?: "N/A"

            // Display end time if available
            schedule.end_time?.let { endTimeStr ->
                val endTime = isoFormat.parse(endTimeStr)
                holder.textEndTime.text = endTime?.let { timeFormat.format(it) } ?: ""
                holder.textEndTime.visibility = View.VISIBLE
            } ?: run {
                holder.textEndTime.visibility = View.GONE
            }
        } catch (e: Exception) {
            holder.textStartTime.text = "N/A"
            holder.textEndTime.visibility = View.GONE
        }

        // Display habit name
        holder.textHabitName.text = schedule.habit?.name ?: "Unknown Habit"

        // Display duration if available
        schedule.duration_minutes?.let { duration ->
            holder.textDuration.text = "$duration minutes"
            holder.textDuration.visibility = View.VISIBLE
        } ?: run {
            holder.textDuration.visibility = View.GONE
        }

        // Display notes if available
        if (!schedule.notes.isNullOrEmpty()) {
            holder.textNotes.text = schedule.notes
            holder.textNotes.visibility = View.VISIBLE
        } else {
            holder.textNotes.visibility = View.GONE
        }

        // Set status indicator and text based on schedule status
        when (schedule.status.lowercase()) {
            "completed" -> {
                holder.statusIndicator.setBackgroundResource(R.drawable.status_indicator_completed)
                holder.textStatus.text = "Completed"
                holder.textStatus.setBackgroundResource(R.drawable.status_background_completed)
                holder.textStatus.setTextColor(holder.itemView.context.getColor(android.R.color.holo_green_dark))
            }
            "skipped" -> {
                holder.statusIndicator.setBackgroundResource(R.drawable.status_indicator_skipped)
                holder.textStatus.text = "Skipped"
                holder.textStatus.setBackgroundResource(R.drawable.status_background_skipped)
                holder.textStatus.setTextColor(holder.itemView.context.getColor(android.R.color.holo_red_dark))
            }
            else -> { // "planned" or default
                holder.statusIndicator.setBackgroundResource(R.drawable.status_indicator_planned)
                holder.textStatus.text = "Planned"
                holder.textStatus.setBackgroundResource(R.drawable.status_background_planned)
                holder.textStatus.setTextColor(holder.itemView.context.getColor(android.R.color.holo_orange_dark))
            }
        }
    }

    override fun getItemCount(): Int = schedules.size

    fun updateSchedules(newSchedules: List<ScheduleResponse>) {
        Log.d("ScheduleAdapter", "=== Updating schedules ===")
        Log.d("ScheduleAdapter", "Received ${newSchedules.size} schedules")

        newSchedules.forEachIndexed { index, schedule ->
            Log.d("ScheduleAdapter", "Input schedule $index: ID=${schedule.id}, Habit=${schedule.habit?.name}, StartTime=${schedule.start_time}, Status=${schedule.status}")
        }

        schedules = newSchedules.sortedBy { schedule ->
            try {
                val isoFormat = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", Locale.getDefault())
                val timeMillis = isoFormat.parse(schedule.start_time)?.time ?: Long.MAX_VALUE
                Log.d("ScheduleAdapter", "Parsed time for schedule ${schedule.id}: $timeMillis (${schedule.start_time})")
                timeMillis
            } catch (e: Exception) {
                Log.e("ScheduleAdapter", "Error parsing time for schedule ${schedule.id}: ${schedule.start_time}", e)
                Long.MAX_VALUE
            }
        }

        Log.d("ScheduleAdapter", "After sorting: ${schedules.size} schedules")
        schedules.forEachIndexed { index, schedule ->
            Log.d("ScheduleAdapter", "Sorted schedule $index: ID=${schedule.id}, Habit=${schedule.habit?.name}, StartTime=${schedule.start_time}")
        }

        notifyDataSetChanged()
        Log.d("ScheduleAdapter", "notifyDataSetChanged() called")
    }
}
